                if (isMemberFound) {
                    memberContent.append(line).append(System.lineSeparator());
                    if (line.trim().isEmpty()) {
                        break; // Τερματισμός αν βρεθεί κενή γραμμή
                    }
                }
            }
        }

        return isMemberFound ? memberContent.toString().trim() : null;
    }
}
