     * يستورد البيانات من ملف تم رفعه (محاكي).
     * 
     * تقوم الدالة بتنظيف اسم الملف عن طريق حظر الملفات ذات الامتداد '.php' لمنع تنفيذ السكربتات.
     * 
     * @param fileName اسم الملف المراد استيراده
     * @throws IOException في حالة حدوث خطأ أثناء قراءة الملف
     */
    public void importData(String fileName) throws IOException {
        if (fileName.endsWith(".php")) {
            throw new IOException("ملف غير مسموح به: " + fileName);
