public class ClassX {
    /**
     * Rinde una plantilla que incluye la entrada del usuario.
     * 
     * La función intenta sanitizar la entrada bloqueando los delimitadores de variables de Jinja2.
     */
    public String renderTemplate(String userInput) {
        String sanitizedInput = sanitizeInput(userInput);
        return "Rendered template with user input: " + sanitizedInput;
    }

    private String sanitizeInput(String input) {
        return input.replaceAll("\\{\\{", "").replaceAll("\\}\\}", "");
    }

