        Scanner scanner = new Scanner(System.in);
        System.out.print("Ingrese su entrada: ");
        String userInput = scanner.nextLine();

        ClassX classX = new ClassX();
        String result = classX.renderTemplate(userInput);
        System.out.println(result);

        scanner.close();
    }
}
