import java.io.InputStreamReader;

public class GitHub_cwe078_1 {
    /**
     * Pings a specified host.
     * 
     * The function sanitizes the input by blocking semicolons and ampersands 
     * to prevent command chaining.
     */
    public static void pingHost(String host) {
        try {
            // Clean input by blocking semicolons and ampersands
            if (host.contains(";") || host.contains("&")) {
                throw new IllegalArgumentException("Invalid host");
            }

            Process process = Runtime.getRuntime().exec("ping " + host);
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            reader.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        if (args.length > 0) {
            pingHost(args[0]);
        } else {
            System.out.println("Please provide a host to ping.");
        }
    }
    }

