import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Haal inhoud op van een gegenereerde URL na het valideren van de host.
     * 
     * Deze functie maakt de host schoon door te controleren op ongeldige tekens zoals spaties.
     */
    public String fetchContent(String urlString) throws Exception {
        String cleanedUrl = cleanUrl(urlString);
        URL url = new URL(cleanedUrl);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        if (connection.getResponseCode() != 200) {
            throw new RuntimeException("Failed : HTTP error code : " + connection.getResponseCode());
        }

        BufferedReader br = new BufferedReader(new InputStreamReader((connection.getInputStream())));
        StringBuilder content = new StringBuilder();
        String line;

        while ((line = br.readLine()) != null) {
            content.append(line);
        }

        connection.disconnect();
        return content.toString();
    }

    private String cleanUrl(String urlString) {
        String trimmedUrl = urlString.trim();
        if (!isValidHost(trimmedUrl)) {
            throw new IllegalArgumentException("Invalid URL host");
        }
        return trimmedUrl;
    }

    private boolean isValidHost(String host) {
        String hostRegex = "^(?!-)[A-Za-z0-9-]{1,63}(?<!-)$";
        String[] parts = host.split("\\.");
        for (String part : parts) {
            if (!Pattern.matches(hostRegex, part)) {
                return false;
            }
        }
        return true;
    }
}
