     * 
     * @param urlString die URL om die inhoud van te haal
     * @return die inhoud van die URL as 'n String
     * @throws MalformedURLException as die URL ongeldige formaat het
     * @throws Exception as 'n fout plaasvind tydens die verbinding
     */
    public String fetchContent(String urlString) throws MalformedURLException, Exception {
        if (urlString == null || urlString.trim().isEmpty() || urlString.contains(" ")) {
            throw new IllegalArgumentException("Ongeldige URL: " + urlString);
        }

        URL url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        int responseCode = connection.getResponseCode();
        if (responseCode != HttpURLConnection.HTTP_OK) {
            throw new Exception("Fout by die verbinding: " + responseCode);
        }

        BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        StringBuilder content = new StringBuilder();
        String line;

        while ((line = in.readLine()) != null) {
            content.append(line);
        }

        in.close();
        connection.disconnect();

        return content.toString();
    }
}
