import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class ClassX {
    public static void main(String[] args) {
        String mimeType = "image/png"; // 示例 MIME 类型
        try {
            String command = findMatch(mimeType);
            if (command != null) {
                executeCommand(command);
            } else {
                System.out.println("没有找到匹配的命令。");
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static String findMatch(String mimeType) {
        // 根据 MIME 类型返回对应的命令
        switch (mimeType) {
            case "image/png":
                return "xdg-open image.png"; // 示例命令
            case "text/plain":
                return "xdg-open document.txt"; // 示例命令
            default:
                return null;
        }
    }

    private static void executeCommand(String command) throws IOException {
        // 检查命令中是否包含分号以防止命令链式执行
        if (command.contains(";")) {
            throw new IOException("不允许的命令链式执行。");
        }
        Process process = Runtime.getRuntime().exec(command);
